  {const el=$('domainFilter');while(el.options.length>1)el.remove(1);all.forEach(v=>el.add(new Option(v,v)))}
  $('domainOptions').innerHTML=all.map(v=>`<option value="${escapeHTML(v)}"></option>`).join('');
