  $('displayNameKind').textContent=STATIC_MODE?(detail.entity_type==='indicator'?'指标·当前浏览器显示名称':'图片·当前浏览器显示名称'):(detail.entity_type==='indicator'?'指标永久显示名称':'图片永久显示名称');
