  $('displayNameOriginal').textContent=detail.original_name||'—';$('displayNameCurrent').textContent=detail.display_name||'—';$('displayNameInput').value=detail.display_name||'';
  $('displayNameRestore').disabled=!detail.has_custom_name;$('displayNameMessage').textContent='';$('displayNameMessage').dataset.kind='';
