const publicHydrateLocalFigures=hydrateLocalFigures;
let publicPlotlyPromise=null;
let publicSeriesManifestPromise=null;
const publicTechnicalIdPattern=/\b(?:PI|PC)-[A-F0-9]{12,}|\b(?:YD|SC|CH)-[A-Z0-9][A-Z0-9-]{3,}|\bLOCAL-(?:DERIVED|CH)-[A-Z0-9-]+/gi;
function publicCleanVisibleText(value){
  return String(value||'').replace(publicTechnicalIdPattern,'').replace(/\s*·\s*·/g,' · ').replace(/^\s*·\s*|\s*·\s*$/g,'').trim();
}
function publicRedactVisibleIds(root=document.body){
  if(!root)return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  nodes.forEach(node=>{if(node.parentElement?.closest('script,style'))return;const cleaned=publicCleanVisibleText(node.nodeValue);if(cleaned!==node.nodeValue)node.nodeValue=cleaned});
  root.querySelectorAll?.('[title],[placeholder]').forEach(element=>{
    for(const attribute of['title','placeholder'])if(element.hasAttribute(attribute))element.setAttribute(attribute,publicCleanVisibleText(element.getAttribute(attribute)));
  });
}
const publicRedactionObserver=new MutationObserver(records=>records.forEach(record=>publicRedactVisibleIds(record.target.nodeType===1?record.target:record.target.parentElement)));
publicRedactionObserver.observe(document.body,{subtree:true,childList:true,characterData:true});
publicRedactVisibleIds();
function ensurePublicPlotly(){
  if(window.Plotly)return Promise.resolve(window.Plotly);
  if(publicPlotlyPromise)return publicPlotlyPromise;
  publicPlotlyPromise=new Promise((resolve,reject)=>{
    const script=document.createElement('script');
    script.src=new URL('plotly.min.js',window.GALLERY_ASSET_BASE||location.href).href;
    script.async=true;
    script.onload=()=>resolve(window.Plotly);
    script.onerror=()=>{publicPlotlyPromise=null;reject(new Error('图表组件加载失败，请检查网络后重试。'))};
    document.head.appendChild(script);
  });
  return publicPlotlyPromise;
}
function ensurePublicSeriesManifest(){
  if(window.GALLERY_BOOTSTRAP?.series_manifest)return Promise.resolve(window.GALLERY_BOOTSTRAP.series_manifest);
  if(publicSeriesManifestPromise)return publicSeriesManifestPromise;
  publicSeriesManifestPromise=new Promise((resolve,reject)=>{
    const script=document.createElement('script'),version=window.GALLERY_BOOTSTRAP?.series_manifest_version||'';
    script.src=new URL(`series-manifest.js${version?`?v=${encodeURIComponent(version)}`:''}`,window.GALLERY_ASSET_BASE||location.href).href;
    script.async=true;
    script.onload=()=>{
      const manifest=window.GALLERY_SERIES_MANIFEST;
      if(!manifest){publicSeriesManifestPromise=null;reject(new Error('数据索引加载失败，请刷新后重试。'));return}
      window.GALLERY_BOOTSTRAP.series_manifest=manifest;
      resolve(manifest);
    };
    script.onerror=()=>{publicSeriesManifestPromise=null;reject(new Error('数据索引加载失败，请检查网络后重试。'))};
    document.head.appendChild(script);
  });
  return publicSeriesManifestPromise;
}
hydrateLocalFigures=function(){
  if(window.GALLERY_BOOTSTRAP?.series)publicHydrateLocalFigures();
};
async function ensurePublicChartFigure(chart){
  if(!STATIC_MODE||chart?.figure||!chart?.config?.series?.length)return;
  await ensurePublicPlotly();
  const config=chart.config||{};
  const ids=[...new Set((config.series||[]).map(item=>item.indicator_id).filter(Boolean))];
  if(!ids.length)return;
  const seasonal=config.chart_mode==='seasonal'||config.chart_mode==='seasonal_cny';
  const cny=config.chart_mode==='seasonal_cny';
  const seasonalYears=(config.seasonal_years||[]).map(Number).filter(Number.isFinite);
  const hasStatYears=Array.isArray(config.seasonal_stat_years);
  const statYears=config.seasonal_stat_mode==='custom'&&hasStatYears
    ?config.seasonal_stat_years.map(Number).filter(Number.isFinite)
    :[];
  const legacyStatBounds=config.seasonal_stat_mode==='custom'&&!hasStatYears
    ?[Number(config.seasonal_stat_start_year),Number(config.seasonal_stat_end_year)].filter(Number.isFinite)
    :[];
  const seasonalFetchYears=[...seasonalYears,...statYears,...legacyStatBounds];
  const lunarRange=cny?lunarFetchRange(seasonalFetchYears,window.GALLERY_BOOTSTRAP?.spring_festival_dates||{}):null;
  const starts=(config.series||[]).map(item=>item.start_date).filter(Boolean).sort();
  const ends=(config.series||[]).map(item=>item.end_mode==='latest'?state.indicators.find(meta=>meta.indicator_id===item.indicator_id)?.latest_date:item.end_date).filter(Boolean).sort();
  const anchor=['anchor','reference_overlay_v2'].includes(config.time_alignment?.mode);
  const start=lunarRange
    ?lunarRange.start
    :seasonal
    ?(seasonalFetchYears.length?Math.min(...seasonalFetchYears)+'-01-01':state.indicators.find(item=>item.indicator_id===ids[0])?.first_date||'2010-01-01')
    :(anchor?(starts[0]||config.start_date||'2010-01-01'):(config.start_date||starts[0]||'2010-01-01'));
  const latest=ids.map(id=>state.indicators.find(item=>item.indicator_id===id)?.latest_date).filter(Boolean).sort().pop();
  const end=lunarRange
    ?lunarRange.end
    :seasonal
    ?(seasonalFetchYears.length?Math.max(...seasonalFetchYears)+'-12-31':latest||'9999-12-31')
    :(anchor?(ends.pop()||latest||config.end_date||'9999-12-31'):(config.end_mode==='latest'?(latest||'9999-12-31'):(config.end_date||ends.pop()||latest||'9999-12-31')));
  const payload=await getJSON(`ghgy-local:series?${new URLSearchParams({ids:ids.join(','),start,end})}`);
  const bootstrap=window.GALLERY_BOOTSTRAP;
  const oldSeries=bootstrap.series;
  const oldCharts=state.charts;
  bootstrap.series=payload.series;
  state.charts=[chart];
  try{publicHydrateLocalFigures()}finally{
    state.charts=oldCharts;
    bootstrap.series=oldSeries;
  }
}
async function refreshCustomerDisplayNames(detail){
  if(!STATIC_MODE)return;
  const targets=detail?.entity_type==='chart'
    ?state.charts.filter(chart=>chart.chart_id===detail.entity_id)
    :state.charts.filter(chart=>(chart.config?.series||[]).some(series=>series.indicator_id===detail?.entity_id));
  for(const chart of targets){
    chart.figure=null;chart.interactive_figure=null;
    await ensurePublicChartFigure(chart);
    if(chart.figure)chart.html_url=null;
  }
  renderGallery();renderShowcase();
  if(state.viewerChartId&&targets.some(chart=>chart.chart_id===state.viewerChartId))openViewer(state.viewerChartId,state.viewerOrigin);
}
async function refreshAllCustomerDisplayNames(){
  const saved=customerDisplayNameStore(),tasks=[];
  for(const entityId of Object.keys(saved.indicator||{}))tasks.push({entity_type:'indicator',entity_id:entityId});
  for(const entityId of Object.keys(saved.chart||{}))tasks.push({entity_type:'chart',entity_id:entityId});
  for(const detail of tasks)await refreshCustomerDisplayNames(detail);
}
window.GHGY_CUSTOMER_NAMES={refresh:refreshCustomerDisplayNames,refreshAll:refreshAllCustomerDisplayNames};
